func (t *memoTable) alloc() *memoEntry {
	if len(t.slab) == 0 {
		if t.used < len(t.chunks) {
			t.slab = t.chunks[t.used]
		} else {
			t.slab = make([]memoEntry, 256)
			t.chunks = append(t.chunks, t.slab)
		}
		t.used++
	}
	e := &t.slab[0]
	t.slab = t.slab[1:]
	return e
}

