// BoolLit is the terminal type BoolLit.
type BoolLit struct {
	Span
	Text string
}

// BytesLit is the terminal type BytesLit.
type BytesLit struct {
	Span
	Text string
}

// DoubleLit is the terminal type DoubleLit.
