func tl0(a *tslabs, v any) []Expr {
	if v == nil {
		return nil
	}
	n, _ := v.(*tnode)
	if n == nil {
		return []Expr{} // another node (an Error), as conversion makes an empty list of it
	}
	out := astSlice(&a.tl0Chunk, len(n.kids))
	for i, c := range n.kids {
		out[i] = tAs[Expr](tpub(c))
	}
	return out
}

func tl1(a *tslabs, v any) []*Entry {
	if v == nil {
		return nil
	}
	n, _ := v.(*tnode)
	if n == nil {
		return []*Entry{} // another node (an Error), as conversion makes an empty list of it
	}
	out := astSlice(&a.tl1Chunk, len(n.kids))
	for i, c := range n.kids {
		out[i] = tAs[*Entry](c)
	}
	return out
}

func tl2(a *tslabs, v any) []*Field {
	if v == nil {
		return nil
	}
	n, _ := v.(*tnode)
	if n == nil {
		return []*Field{} // another node (an Error), as conversion makes an empty list of it
	}
	out := astSlice(&a.tl2Chunk, len(n.kids))
	for i, c := range n.kids {
		out[i] = tAs[*Field](c)
	}
	return out
}

// tslabs holds the chunks the typed values of a parse are allocated from.
type tslabs struct {
	tBoolLit     []BoolLit
	tBytesLit    []BytesLit
	tDoubleLit   []DoubleLit
	tIdent       []Ident
	tIntLit      []IntLit
	tName        []Name
	tNullLit     []NullLit
	tStringLit   []StringLit
	tUintLit     []UintLit
	tBinary      []Binary
	tCall        []Call
	tConditional []Conditional
	tEntry       []Entry
	tField       []Field
	tIndex       []Index
	tListLit     []ListLit
	tMapLit      []MapLit
	tMessageLit  []MessageLit
	tOptional    []Optional
	tParen       []Paren
	tSelect      []Select
	tUnary       []Unary
	tl0Chunk     []Expr
	tl1Chunk     []*Entry
	tl2Chunk     []*Field
}

// ParseAST parses the input like Parse and returns the result as typed values. If the parse recovered
// from errors, the result is returned together with SyntaxErrors; an Error node where a struct or
// terminal type is expected becomes nil.
// It builds the values directly, without the nodes Parse returns.
func ParseAST(input string, unit ...Unit) (Expr, error) {
	a := &tslabs{}
	return tparse(trules[0], input, unit, a, func(v any) Expr { return tAs[Expr](tpub(v)) })
}

